import Phaser from "phaser";
import { PALETTE } from "../ui";
import { demoStart } from "../state/demo";

export class BootScene extends Phaser.Scene {
  constructor() {
    super("Boot");
  }

  preload() {
    this.cameras.main.setBackgroundColor(PALETTE.cream);
    const bar = this.add.rectangle(60, 320, 0, 8, PALETTE.hotpink).setOrigin(0, 0.5);
    this.load.on("progress", (p: number) => bar.setSize(240 * p, 8));
    this.add.rectangle(180, 320, 240, 8, PALETTE.pink).setDepth(-1);
    // Generated by `python3 tools/sprites/gen.py`.
    this.load.atlas("items", "assets/items.png", "assets/items.json");
    this.load.atlas("items64", "assets/items64.png", "assets/items64.json");
    this.load.atlas("ui", "assets/ui.png", "assets/ui.json");
    // Built by `python3 tools/sprites/pack.py` from the PixelFoodThemedAssets pack.
    this.load.atlas("food", "assets/food.png", "assets/food.json");
    // Built by `python3 tools/font/build.py`.
    this.load.bitmapFont("mama", "assets/font/mama.png", "assets/font/mama.xml");
    this.load.bitmapFont("mama_white", "assets/font/mama_white.png", "assets/font/mama_white.xml");
  }

  create() {
    for (const key of ["items", "items64", "ui", "food", "mama", "mama_white"]) this.textures.get(key).setFilter(Phaser.Textures.FilterMode.NEAREST);
    this.scene.start(demoStart() ?? "Title");
  }
}
